SET NAMES utf8mb4;
START TRANSACTION;
UPDATE seasoning s LEFT JOIN seasoning correct ON correct.owner_user_id='platform' AND correct.seasoning_name=CONVERT(0xe89a9de6b2b9 USING utf8mb4) SET s.seasoning_name=CONVERT(0xe89a9de6b2b9 USING utf8mb4), s.update_time=NOW() WHERE s.scope='platform' AND s.owner_user_id='platform' AND s.seasoning_name=CONVERT(0xe88097e6b2b9 USING utf8mb4) AND correct.id IS NULL;
UPDATE recipe_seasoning_rel r JOIN seasoning s ON s.id=r.seasoning_id SET r.seasoning_name=CONVERT(0xe89a9de6b2b9 USING utf8mb4), r.update_time=NOW() WHERE s.scope='platform' AND s.owner_user_id='platform' AND s.seasoning_name=CONVERT(0xe89a9de6b2b9 USING utf8mb4) AND r.seasoning_name=CONVERT(0xe88097e6b2b9 USING utf8mb4);
COMMIT;
